#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/getlago-postgres-partman-15.0-alpine-arm64-oci ] || "$F" docker.io/getlago/postgres-partman sha256:4bfb4eb22be0f9149efb04724ecb573ad1374a6b8b717bece93cae50491cc68f getlago/postgres-partman:15.0-alpine images/getlago-postgres-partman-15.0-alpine-arm64-oci
[ "$A" = arm64 ] || [ -f images/getlago-postgres-partman-15.0-alpine-amd64.docker.tar ] || "$F" docker.io/getlago/postgres-partman sha256:ff4616c24367f3643aac27061a0c4e757ca8f78af967249cb4b3fd64049d290d getlago/postgres-partman:15.0-alpine images/getlago-postgres-partman-15.0-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/redis-7.4.7-alpine-arm64-oci ] || "$F" docker.io/library/redis sha256:eaa5baba4031beadea0a970d578807f96ff6caf9282f1878f316059ed889a178 redis:7.4.7-alpine images/redis-7.4.7-alpine-arm64-oci
[ "$A" = arm64 ] || [ -f images/redis-7.4.7-alpine-amd64.docker.tar ] || "$F" docker.io/library/redis sha256:b9f6cf0cab55fdd102fd2182deeae150457943d33439d18c6e2fc5666d3228c1 redis:7.4.7-alpine images/redis-7.4.7-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/getlago-api-v1.57.0-arm64-oci ] || "$F" docker.io/getlago/api sha256:8e74b935cc902b363ecbd2050fef0375721ce5e21f2f59e39aece35e79c63d4c getlago/api:v1.57.0 images/getlago-api-v1.57.0-arm64-oci
[ "$A" = arm64 ] || [ -f images/getlago-api-v1.57.0-amd64.docker.tar ] || "$F" docker.io/getlago/api sha256:8ccbea4191f30d85ee98dd0fa9b7091128286f764aedb122831e78180fa69faa getlago/api:v1.57.0 images/getlago-api-v1.57.0-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/getlago-api-v1.57.0-amd64.docker.tar images/getlago-postgres-partman-15.0-alpine-amd64.docker.tar images/redis-7.4.7-alpine-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/getlago-api-v1.57.0-arm64-oci images/getlago-postgres-partman-15.0-alpine-arm64-oci images/redis-7.4.7-alpine-arm64-oci
